LABELS = ("fruit", "vehicle")


class Harness:
    def run(self, task, model, trace):
        reply = model("classify: " + task["input"]).strip().lower()
        for label in LABELS:
            if label in reply:
                return {"output": label}
        return {"output": LABELS[-1]}

